  '7237959000011270034': {"name": "Asmaa Serhan", "title": "Mentor", "photo": null, "languages": ["English", "Arabic"], "bio": "I’m a biomedical engineer, AI and data science professional, entrepreneur, and mentor with experience across innovation, entrepreneurship, professional development, and event management. Over the years, I have supported young people in developing their ideas, strengthening their skills, and transforming concepts into practical projects. I also bring hands-on corporate experience in managing professional events and cross-functional projects. As a mentor, I aim to create a practical and engaging learning experience where participants can build useful skills, gain confidence, and apply what they learn to real-world opportunities.", "fields": ["Career Counseling and Development", "Artificial Intelligence (AI)", "Business Coaching", "Event Planning"], "specialties": [], "location": "Lebanon", "video": null, "courses": ["Coaching for Entrepreneurs", "CV Writing and Personal Branding Crash Course!", "Coaching for Leadership Development", "Consultation", "Managing Corporate Events"]},
