  '7237959000010616035': {"name": "Eddy Keyrouz", "title": "Mentor", "photo": null, "languages": ["English", "Arabic"], "bio": "I'm a passionate language teacher from Lebanon with a background in Translation and Communication and experience teaching students from different countries and age groups. I teach Spanish, English, Arabic, and I also speak French, Portuguese and I’m currently learning Chinese which helps me understand the challenges language learners face. My lessons are practical, friendly, and adapted to each student’s level and goals. Whether you want to improve your speaking, pronunciation, grammar, vocabulary, or simply become more confident communicating, I’m here to help you progress step by step. I believe that learning a language should be enjoyable, interactive, and useful in real-life situations. Let’s improve your language skills together! ?", "fields": ["Young Learners", "Lebanese Baccalaureate School Tutoring", "Arabic", "English"], "specialties": [], "location": "Beirut, Lebanon", "video": null, "courses": ["English Writing Mastery", "Speaking & Pronunciation Fluency", "Business English Communication", "English Grammar Mastery", "Intermediate General English", "Beginner General English", "Elementary Arabic (Grades 1 to 6) LB", "Academic English Mastery", "Arabic Reading", "Elementary French (Grades 1 to 6) LB"]},
  '7237959000002674001': {"name": "Elia Youssef", "title": "Mentor", "photo": null, "languages": ["English", "Arabic"], "bio": "I’m an Unreal Engine Technical Director, 3D visualization specialist, and instructor with a degree in Interior Architecture and 15+ years of experience across architectural visualization, 3D modeling, VR/AR, game design, and real-time development. My work spans high-end ArchViz, interactive walkthroughs, immersive VR experiences, virtual production, pixel streaming, and large-scale Unreal Engine worlds. With 8 years of teaching experience, I’ve trained students and professionals in 3ds Max, V-Ray, Unreal Engine, and production-ready visualization workflows. My teaching is grounded in real industry experience, helping learners build practical, job-ready skills in ArchViz, 3D production, VR, and real-time interactive design.", "fields": ["Architecture", "Digital Tools & Automation", "Interior Design", "Artificial Intelligence (AI)", "OMT"], "specialties": ["AI Coding"], "location": "Beirut, Lebanon", "video": null, "courses": ["Claude AI", "The Content Creator AI Engine", "Mastering V-Ray", "Consultation", "Mastering 3ds Max"]},
  '7237959000005321093': {"name": "Jane Saliba", "title": "Mentor", "photo": null, "languages": ["English", "Arabic"], "bio": "I have been teaching English and Arabic for more than 10 years now. I hold the CELTA certificate from The University of Cambridge which helped me use effective teaching techniques with students of all ages and levels.", "fields": ["American Curriculum School Tutoring", "Lebanese Baccalaureate School Tutoring", "Arabic", "English"], "specialties": [], "location": "Ajaltoun, Lebanon", "video": null, "courses": ["English Writing Mastery", "English Grammar Mastery", "Speaking & Pronunciation Fluency", "Business English Communication", "Beginner General English", "Middle School Arabic (Grades 7 to 9) LB", "Creative Writing in Arabic", "Intermediate General English", "Consultation", "Middle School English (Grades 7 to 9) LB"]},
